int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);

int main(int argc, char **argv)
{
        int ret;
        unsigned char buf[64*1024];

        ret = fread(buf, 1, sizeof(buf), stdin);
        if (ret <= 0)
                return 0;

        return LLVMFuzzerTestOneInput(buf, ret);
}

